/**
 * BrandMessageBubble — extracted verbatim from brand-message.tsx.
 *
 * Single iMessage-style outgoing bubble (cream, right-aligned, sharp
 * bottom-right corner). Typing dots fade in first, then the bubble pops.
 *
 * brand-message.tsx is refactored to consume this primitive; both paths
 * render byte-identical DOM.
 */

import * as React from "react";
import { interpolate } from "../../react-animations/animation-utils";
import { stripPipe } from "../../scene-templates/text-utils";
import { renderWithEmoji } from "../../emoji/emoji-text";

const CLAMP = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
const BUBBLE_BG = "rgba(245,242,238,0.92)";
const BUBBLE_TEXT = "#1c1c1e";
const DOT_COLOR = "#8C8C92";

function easeOutBack(t: number): number {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
}

const TAIL_WITH_EMOJI = /(\S+)(\s+)([\p{Extended_Pictographic}\p{Emoji_Modifier}\u{FE0E}\u{FE0F}\u{200D}]+)\s*$/u;

/**
 * Render a message and glue the trailing emoji cluster to the last word
 * via a `white-space: nowrap` span, so the emoji can NEVER wrap to its
 * own line at the bottom of the bubble.
 *
 * Why a span and not just NBSP: an earlier fix used U+00A0 (non-breaking
 * space) between the last word and the trailing emoji. NBSP works in the
 * live DOM (preview) but the modern-screenshot SVG-as-image render path
 * does NOT consistently honor NBSP — the emoji wrapped to its own line
 * in the exported MP4 even with NBSP in place (verified by extracting a
 * frame from a real export via ffmpeg). `white-space: nowrap` on a span
 * is a hard CSS rendering rule that all renderers respect.
 *
 * Scoped to the LAST trailing emoji cluster preceded by a word: messages
 * with an emoji mid-sentence still wrap naturally on width. Covers the
 * pictographic set + emoji modifiers + variation selectors (FE0E/F) +
 * ZWJ for composite emoji like the astronaut.
 */
function renderMessageWithEmojiTail(text: string, fontSizePx: number): React.ReactNode {
  const match = TAIL_WITH_EMOJI.exec(text);
  if (!match || match.index === undefined) {
    // No trailing-emoji tail: still image any mid-sentence color emoji so all
    // three render paths agree on the mapped emoji PNG.
    return renderWithEmoji(text, fontSizePx);
  }
  const [, lastWord, space, emoji] = match;
  const leading = text.slice(0, match.index);
  return (
    <>
      {renderWithEmoji(leading, fontSizePx)}
      <span style={{ whiteSpace: "nowrap" }}>
        {lastWord}
        {space}
        {renderWithEmoji(emoji, fontSizePx)}
      </span>
    </>
  );
}

function popIn(t: number, start: number, dur = 0.4): number {
  if (t <= start) return 0;
  if (t >= start + dur) return 1;
  return easeOutBack((t - start) / dur);
}

// ─── Typed component (direct use from templates) ────────────────

export interface BrandMessageBubbleProps {
  progress: number;
  sceneDuration: number;
  /** Sender label (italic, top-left of bubble) */
  brandName: string;
  /** Message text */
  message: string;
  width: number;
  height: number;
  safeZone: { top: number; right: number; bottom: number; left: number };
}

export const BrandMessageBubble: React.FC<BrandMessageBubbleProps> = ({
  progress,
  sceneDuration,
  brandName: rawBrandName,
  message: rawMessage,
  width,
  height,
  safeZone,
}) => {
  const isLandscape = width > height;
  const s = isLandscape
    ? (Math.min(width, height) / 534) * 1.3
    : width / 534;
  const brandName = stripPipe(rawBrandName);
  const message = stripPipe(rawMessage);
  const realTimeSeconds = progress * sceneDuration;

  const typingStart = 0.10;
  const bubbleStart = 0.38;
  const typingPop = popIn(progress, typingStart, 0.10);
  const typingFade = interpolate(progress, [bubbleStart - 0.06, bubbleStart], [1, 0], CLAMP);
  const showTyping = progress >= typingStart && progress < bubbleStart;

  const bubblePop = popIn(progress, bubbleStart, 0.18);
  const showBubble = progress >= bubbleStart;

  const topPad = Math.max(safeZone.top, height * 0.25);
  const sidePad = Math.max(safeZone.left, width * 0.06);

  return (
    <div
      style={{
        position: "absolute",
        top: topPad,
        left: sidePad,
        right: sidePad,
        display: "flex",
        justifyContent: "flex-end",
      }}
    >
      {showTyping && (
        <div
          style={{
            opacity: typingPop * typingFade,
            transform: `translateY(${(1 - typingPop) * 8 * s}px)`,
            background: BUBBLE_BG,
            borderRadius: 18 * s,
            padding: `${12 * s}px ${16 * s}px`,
            display: "flex",
            gap: 5 * s,
            alignItems: "center",
            boxShadow: `0 ${1 * s}px ${4 * s}px rgba(0,0,0,0.10)`,
          }}
        >
          {[0, 1, 2].map((j) => {
            const phase = (realTimeSeconds * 1.6 + j * 0.2) % 1;
            const y = Math.sin(phase * Math.PI * 2) * 2.5 * s;
            const op = 0.45 + 0.55 * Math.max(0, Math.sin(phase * Math.PI));
            return (
              <div
                key={j}
                style={{
                  width: 7 * s,
                  height: 7 * s,
                  borderRadius: 3.5 * s,
                  background: DOT_COLOR,
                  transform: `translateY(${-y}px)`,
                  opacity: op,
                }}
              />
            );
          })}
        </div>
      )}

      {showBubble && (
        <div
          style={{
            // `width: max-content` forces the bubble to size to its
            // natural one-line content width up to `maxWidth`. Without
            // this, modern-screenshot's foreignObject text shaping (the
            // export path) was using an intrinsic width well below
            // `maxWidth`, breaking text that would have fit on one line
            // in the live DOM — even after the NBSP fix glued the
            // trailing emoji to the last word. With `max-content` +
            // `maxWidth`, the bubble grows up to the cap on a single
            // line, then wraps naturally inside the cap for genuinely
            // long messages.
            width: "max-content",
            maxWidth: width * 0.86,
            // Render with native system fonts in BOTH paths. The export
            // pipeline turns the iframe DOM into an SVG and loads it via
            // <img src="data:image/svg+xml,…">, and SVG-as-image is a
            // sandboxed graphics context that does NOT load @font-face
            // resources (data: or otherwise — this is a browser security
            // model, not a CSP issue). Inter therefore never resolves in
            // the export; the SVG falls back to Helvetica/Helvetica Neue,
            // which is wider at the same point size, and "We built this
            // for you ❤️" wraps inside the pinned bubble box even though
            // the iframe's Inter rendering fit on one line. Naming the
            // system font explicitly here makes the iframe ALSO use that
            // same OS-native font, so preview and export compute identical
            // widths and both fit on one line. See PRs #598/#599/#604 for
            // the months of font-embed work that this finally closes out.
            fontFamily: '"Helvetica Neue", Helvetica, Arial, sans-serif',
            background: BUBBLE_BG,
            color: BUBBLE_TEXT,
            borderRadius: `${22 * s}px ${22 * s}px 0 ${22 * s}px`,
            padding: `${14 * s}px ${18 * s}px ${12 * s}px`,
            fontSize: 23 * s,
            lineHeight: `${29 * s}px`,
            fontWeight: 400,
            opacity: bubblePop,
            transform: `translateY(${(1 - bubblePop) * 8 * s}px) scale(${0.96 + 0.04 * bubblePop})`,
            transformOrigin: "right top",
            boxShadow: `0 ${2 * s}px ${10 * s}px rgba(0,0,0,0.14)`,
          }}
        >
          <div
            style={{
              fontSize: 14 * s,
              fontStyle: "italic",
              fontWeight: 400,
              color: "rgba(0,0,0,0.45)",
              lineHeight: 1.2,
              marginBottom: 6 * s,
            }}
          >
            {brandName}
          </div>
          {renderMessageWithEmojiTail(message, 23 * s)}
        </div>
      )}
    </div>
  );
};

/**
 * EmojiText / renderWithEmoji — split a string into text runs + color-emoji
 * runs, rendering each color emoji as an inline emoji-PNG <img> (via <Emoji>)
 * while leaving everything else as plain text.
 *
 * Why this exists: raw-unicode emoji fall through to the OS emoji font (Mac =
 * Apple, Linux = Noto), so the three render paths (preview / client SVG export
 * / server Puppeteer) disagree. Wrapping every template/AI-supplied string here
 * makes ALL color emoji render as the same mapped PNG in all three.
 *
 * What it does NOT touch: monochrome symbols (★ ✦ ✓ → ↑ …). Those render
 * identically as text across OSes, and imaging them would be wrong. The gate
 * is `emojiToDataUri()` — only clusters that resolve to a PNG in the
 * map become <img>; anything else (monochrome symbols, unmapped/custom
 * emoji, skin-tone variants not in the set) stays raw text.
 *
 * Segmentation: grapheme clusters via Intl.Segmenter so ZWJ sequences
 * (👩‍💻) and skin-tone modifiers (👍🏽) stay single units. Adjacent emoji
 * clusters each render as their own <img> in sequence.
 *
 * Sizing: each emoji <img> is sized to `fontSizePx` (the surrounding font
 * size) so the emoji box matches a glyph box — width/line-count stay
 * ~identical to the raw-text layout, which keeps fitTextSize / archetype
 * char-count measurement valid (all string-based, never DOM-measured).
 */

import * as React from "react";
import { Emoji, emojiToDataUri } from "./index";

// Coarse "is this cluster a color-emoji candidate?" test. Deliberately broad:
// the real decision is whether emojiToDataUri() resolves it to a mapped PNG.
// This regex only needs to (a) catch the OS-divergent color ranges and (b)
// avoid flagging plain text/whitespace so we don't merge text into emoji runs.
//
//  - \u{1F000}-\u{1FAFF}  — main emoji planes (most pictographs)
//  - \u{2600}-\u{27BF}    — misc symbols + dingbats (color when + FE0F)
//  - \u{2B00}-\u{2BFF}    — stars/arrows block (⭐ lives here)
//  - \u{1F1E6}-\u{1F1FF}  — regional indicators (flags)
//  - \u{1F3FB}-\u{1F3FF}  — skin-tone modifiers
//  - \u{FE0F} | \u{200D} | \u{20E3} — VS16 / ZWJ / keycap combiners
//
// Combining/joiner codepoints (FE0F, ZWJ, keycap) are matched via alternation
// rather than inside the character class — eslint's
// no-misleading-character-class flags combining chars inside `[...]`, and
// alternation is equivalent here (we only test, never capture).
const EMOJI_CANDIDATE =
  /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{1F1E6}-\u{1F1FF}]|[\u{1F3FB}-\u{1F3FF}]|\u{FE0F}|\u{200D}|\u{20E3}/u;

function isEmojiCandidate(cluster: string): boolean {
  return EMOJI_CANDIDATE.test(cluster);
}

/** Split text into grapheme clusters (ZWJ + skin-tone safe). */
function toGraphemes(text: string): string[] {
  const Seg = (Intl as unknown as { Segmenter?: typeof Intl.Segmenter }).Segmenter;
  if (Seg) {
    const seg = new Seg(undefined, { granularity: "grapheme" });
    const out: string[] = [];
    for (const { segment } of seg.segment(text)) out.push(segment);
    return out;
  }
  // Fallback: code-point spread. Won't keep ZWJ/skin-tone as single units, so
  // those land as separate clusters; emojiToDataUri's FE0F tolerance + the raw
  // fallback keep them from breaking. Modern browsers all have Segmenter.
  return Array.from(text);
}

export interface RenderWithEmojiOptions {
  /** vertical-align passed to each <Emoji>. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra style merged onto each emoji <img>. */
  emojiStyle?: React.CSSProperties;
}

/**
 * Split `text` into an array of React nodes — plain-text strings interleaved
 * with <Emoji> images for every mapped color emoji. Returns a single-element
 * `[text]` fast-path when there are no color emoji (the common case), so
 * non-emoji text pays ~one regex test.
 *
 * @param text         the string to render
 * @param fontSizePx   surrounding font size in px (emoji box = this size)
 */
export function renderWithEmoji(
  text: string,
  fontSizePx: number,
  opts?: RenderWithEmojiOptions,
): React.ReactNode[] {
  if (!text) return [text];
  // Cheap bail-out: if the whole string has no emoji-range codepoint, return
  // it untouched (no segmentation, no array churn) — the hot path for the vast
  // majority of titles/bodies.
  if (!EMOJI_CANDIDATE.test(text)) return [text];

  const clusters = toGraphemes(text);
  const nodes: React.ReactNode[] = [];
  let textBuf = "";
  let key = 0;

  const flushText = () => {
    if (textBuf) {
      nodes.push(textBuf);
      textBuf = "";
    }
  };

  for (const cluster of clusters) {
    const uri = isEmojiCandidate(cluster) ? emojiToDataUri(cluster) : null;
    if (uri) {
      flushText();
      nodes.push(
        <Emoji
          key={`e${key++}`}
          char={cluster}
          size={fontSizePx}
          verticalAlign={opts?.verticalAlign}
          style={opts?.emojiStyle}
        />,
      );
    } else {
      textBuf += cluster;
    }
  }
  flushText();
  return nodes;
}

/**
 * Per-code-unit emoji plan for the typewriter archetype, which reveals text
 * one UTF-16 code unit at a time and indexes by `text.length`. We can't just
 * call renderWithEmoji there (it would re-segment and desync the visibleChars
 * counter), so this maps each cluster's START code-unit index to its emoji-PNG
 * data URI and marks the cluster's CONTINUATION indices as covered (render
 * nothing for them — the start index's <img> already spans the whole cluster).
 *
 * Returns null when the text contains no mapped color emoji (the common case),
 * so the typewriter render keeps its plain per-char path.
 */
export interface EmojiTypewriterPlan {
  /** code-unit index → full emoji cluster char (cluster start). */
  starts: Map<number, string>;
  /** code-unit indices that are continuations of a cluster (render nothing). */
  covered: Set<number>;
}

export function planTypewriterEmoji(text: string): EmojiTypewriterPlan | null {
  if (!text || !EMOJI_CANDIDATE.test(text)) return null;
  const starts = new Map<number, string>();
  const covered = new Set<number>();
  let idx = 0;
  let found = false;
  for (const cluster of toGraphemes(text)) {
    const len = cluster.length; // UTF-16 code units
    if (isEmojiCandidate(cluster) && emojiToDataUri(cluster)) {
      found = true;
      // Store the WHOLE cluster char (not just the start unit) so callers can
      // pass it straight to <Emoji> for a correct map lookup.
      starts.set(idx, cluster);
      for (let k = 1; k < len; k++) covered.add(idx + k);
    }
    idx += len;
  }
  return found ? { starts, covered } : null;
}

export interface EmojiTextProps {
  /** The text to render, color emoji replaced with emoji-PNG <img>. */
  children: string;
  /** Surrounding font size in px — sizes each emoji image to match a glyph. */
  fontSize: number;
  verticalAlign?: React.CSSProperties["verticalAlign"];
  emojiStyle?: React.CSSProperties;
}

/**
 * Inline wrapper around renderWithEmoji. Renders a React.Fragment of text +
 * emoji <img> runs. Use where a component currently renders a raw `{text}`
 * child and you have the surrounding font size in px.
 */
export const EmojiText: React.FC<EmojiTextProps> = ({
  children,
  fontSize,
  verticalAlign,
  emojiStyle,
}) => {
  const text = typeof children === "string" ? children : "";
  return <>{renderWithEmoji(text, fontSize, { verticalAlign, emojiStyle })}</>;
};

/**
 * Emoji — render emojis as inline PNG data-URI <img> elements.
 *
 * Why images, not the system emoji font: VanillaSky renders the same scene
 * three ways — real-DOM preview, client SVG-as-image export, server Puppeteer.
 * Raw-unicode emojis fall through to whatever emoji font the OS has (Mac=Apple,
 * Linux=Noto), so preview and export disagree. Inlining each emoji as a
 * data-URI <img> renders the SAME PNG in all three. Critically, the
 * client export rasterizes the frame via <img src="data:image/svg+xml">, which
 * can ONLY load inlined data-URI images (not @font-face, not external URLs) —
 * so data URIs are exactly what works there.
 *
 * Source artwork: emoji-datasource-google (Google Noto emoji set, Apache-2.0).
 * The map ships inside the publicly redistributed skill tarball, and Apple's
 * artwork is not licensed for redistribution — Noto's Apache-2.0 is. The set
 * is swappable via the generator's EMOJI_SET constant
 * (scripts/generate-emoji-map.mjs).
 *
 * Bundle: the generated char→dataURI map is ~1.1MB of base64, so it is
 * LAZY-LOADED via dynamic import and never enters the initial app bundle. The
 * import is kicked off eagerly at module load (below) — long before any export
 * or screenshot — so by the time a frame is captured the map has resolved.
 * Until it resolves, <Emoji> renders the raw unicode char, then re-renders to
 * the image when the map lands. Any emoji not in the map also falls back to the
 * raw char, so nothing ever breaks for custom/unmapped emojis.
 */

import * as React from "react";

let EMOJI_MAP: Record<string, string> | null = null;
let loadPromise: Promise<Record<string, string>> | null = null;
const subscribers = new Set<() => void>();

function loadEmojiMap(): Promise<Record<string, string>> {
  if (loadPromise) return loadPromise;
  loadPromise = import("./emoji-map.generated")
    .then((mod) => {
      EMOJI_MAP = mod.default;
      subscribers.forEach((fn) => fn());
      return EMOJI_MAP;
    })
    .catch((err) => {
      // Network/chunk failure: leave map null → everything falls back to char.
      console.warn("[emoji] failed to load emoji map:", err);
      EMOJI_MAP = {};
      return EMOJI_MAP;
    });
  return loadPromise;
}

// Kick off the load immediately when this module is first imported (app/registry
// init), so the map is ready well before any export or server screenshot.
loadEmojiMap();

/**
 * Resolve once the emoji-PNG map has loaded (or definitively failed). Render
 * paths that capture frames MUST await this before their first capture so they
 * never screenshot a frame while emoji are still raw-unicode chars:
 *   - server: Render.tsx awaits before setting window.__ready
 *   - client export: export-video.ts awaits in the media-preload step
 * The preview path doesn't capture, so it can stay lazy (subscribers re-render
 * char → image when the map lands). On chunk failure this resolves to {} so
 * the await never hangs — everything falls back to the raw char.
 */
export function ensureEmojiMap(): Promise<Record<string, string>> {
  return loadEmojiMap();
}

/**
 * Returns the emoji-PNG data URI for an emoji char, or null if the map hasn't
 * loaded yet or the char isn't in the set (caller should fall back to the char).
 */
export function emojiToDataUri(char: string): string | null {
  if (!EMOJI_MAP) return null;
  const key = (char || "").trim();
  if (EMOJI_MAP[key]) return EMOJI_MAP[key];
  // Tolerate a trailing variation selector mismatch (U+FE0F).
  const stripped = key.replace(/️/g, "");
  if (stripped !== key && EMOJI_MAP[stripped]) return EMOJI_MAP[stripped];
  return null;
}

/** Subscribe to map-loaded so a component re-renders char → image when ready. */
function useEmojiMapReady(): boolean {
  const [, force] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => {
    if (EMOJI_MAP) return;
    const fn = () => force();
    subscribers.add(fn);
    loadEmojiMap();
    return () => {
      subscribers.delete(fn);
    };
  }, []);
  return EMOJI_MAP != null;
}

export interface EmojiProps {
  /** The emoji character(s), e.g. "🎉". */
  char: string;
  /** Box size in px — matches the prior glyph's font-size so layout is identical. */
  size: number;
  /** vertical-align for inline flow. Defaults to a glyph-like baseline nudge. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra styles merged onto the <img> (or fallback <span>). */
  style?: React.CSSProperties;
}

/**
 * Renders an emoji as an inline emoji-PNG <img> when available, else the raw
 * unicode char in a same-size box (so scale/opacity/transform are unchanged).
 */
export const Emoji: React.FC<EmojiProps> = ({ char, size, verticalAlign = "-0.15em", style }) => {
  useEmojiMapReady();
  const uri = emojiToDataUri(char);

  if (!uri) {
    // Fallback: raw char sized to the same box so layout/scale are preserved.
    return (
      <span
        style={{
          fontSize: size,
          lineHeight: 1,
          display: "inline-block",
          ...style,
        }}
      >
        {char}
      </span>
    );
  }

  return (
    <img
      src={uri}
      alt={char}
      width={size}
      height={size}
      style={{
        width: size,
        height: size,
        objectFit: "contain",
        display: "inline-block",
        verticalAlign,
        ...style,
      }}
    />
  );
};
